
/**
 * Purpose: Reusable text-to-speech button for student lessons.
 *
 * Directed by: Edenna Chen
 * Generated by: ChatGPT (OpenAI), GPT-6, 2026-11-05
 * Human edits: Pending review
 * External sources: None
 *
 * Uses built-in browser speech synthesis.
 * No API key or external service required.
 */

import { useEffect, useRef, useState } from 'react';

type ListenButtonProps = {
  text: string;
  label?: string;
};

export default function ListenButton({
  text,
  label = 'Listen',
}: ListenButtonProps) {
  const [speaking, setSpeaking] = useState(false);
  const [supported, setSupported] = useState(false);
  const utteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  useEffect(() => {
    setSupported(
      'speechSynthesis' in window &&
      'SpeechSynthesisUtterance' in window
    );

    return () => {
      if (utteranceRef.current) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  function handleClick() {
    if (!supported || !text.trim()) return;

    if (speaking) {
      window.speechSynthesis.cancel();
      utteranceRef.current = null;
      setSpeaking(false);
      return;
    }

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);

    utterance.lang = 'en-US';
    utterance.rate = 0.85;
    utterance.pitch = 1;

    utterance.onstart = () => setSpeaking(true);
    utterance.onend = () => {
      setSpeaking(false);
      utteranceRef.current = null;
    };
    utterance.onerror = () => {
      setSpeaking(false);
      utteranceRef.current = null;
    };

    utteranceRef.current = utterance;
    window.speechSynthesis.speak(utterance);
  }

  if (!supported) return null;

  return (
    <button
      type="button"
      onClick={handleClick}
      aria-label={speaking ? 'Stop reading aloud' : `Read ${label} aloud`}
      aria-pressed={speaking}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: '8px',
        padding: '9px 14px',
        borderRadius: '10px',
        border: '1px solid #C9B8A6',
        backgroundColor: '#FFF9EF',
        color: '#66364A',
        fontWeight: 600,
        cursor: 'pointer',
      }}
    >
      <span aria-hidden="true">{speaking ? '■' : '🔊'}</span>
      {speaking ? 'Stop' : label}
    </button>
  );
}
